create table public.activities (id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id) on delete cascade,crop_cycle_id uuid not null references public.crop_cycles(id) on delete cascade,activity_type text not null check(activity_type in ('sowing','irrigation','fertilizer','pesticide','weeding','spraying','harvesting','other')),activity_date date not null default current_date,description text,quantity numeric(14,3) check(quantity is null or quantity>=0),unit text,created_at timestamptz not null default now());
create table public.tasks (id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id) on delete cascade,crop_cycle_id uuid not null references public.crop_cycles(id) on delete cascade,title text not null check(char_length(trim(title))>0),due_date date,priority text not null default 'medium' check(priority in ('low','medium','high')),status text not null default 'open' check(status in ('open','in_progress','done','cancelled')),assigned_to text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index activities_farm_id_idx on public.activities(farm_id);create index activities_crop_cycle_id_idx on public.activities(crop_cycle_id);create index tasks_farm_id_idx on public.tasks(farm_id);create index tasks_crop_cycle_id_idx on public.tasks(crop_cycle_id);create index tasks_due_date_idx on public.tasks(due_date);
alter table public.activities enable row level security;alter table public.tasks enable row level security;
create policy "owners select activities" on public.activities for select to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
create policy "owners insert activities" on public.activities for insert to authenticated with check(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())) and exists(select 1 from public.crop_cycles c where c.id=crop_cycle_id and c.farm_id=farm_id));
create policy "owners update activities" on public.activities for update to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid()))) with check(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())) and exists(select 1 from public.crop_cycles c where c.id=crop_cycle_id and c.farm_id=farm_id));
create policy "owners delete activities" on public.activities for delete to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
create policy "owners select tasks" on public.tasks for select to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
create policy "owners insert tasks" on public.tasks for insert to authenticated with check(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())) and exists(select 1 from public.crop_cycles c where c.id=crop_cycle_id and c.farm_id=farm_id));
create policy "owners update tasks" on public.tasks for update to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid()))) with check(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())) and exists(select 1 from public.crop_cycles c where c.id=crop_cycle_id and c.farm_id=farm_id));
create policy "owners delete tasks" on public.tasks for delete to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
grant select,insert,update,delete on public.activities,public.tasks to authenticated;